"""OpenWrt Router: tests (kit-generated, adapted to the read-only policy). They pass against the emulator;
run them again with the real transport before recording hardware evidence."""
import json
import unittest

from src.adapters.openwrt_router import (OpenwrtRouter, OpenwrtRouterBlocked, OpenwrtRouterError,
                                         OpenwrtRouterTransport, _host_allowed)
from src.adapters.openwrt_router_emulator import OpenwrtRouterEmulator
from src.fabric.openwrt_router_ingest import ingest_openwrt_router
from src.fabric.registry import Registry


class OpenwrtRouterTests(unittest.TestCase):
    def setUp(self):
        self.emu = OpenwrtRouterEmulator()
        self.dev = OpenwrtRouter(self.emu)

    def test_facts(self):
        names = {f['name']: f['value'] for f in self.dev.facts()}
        self.assertEqual(names, {'uptime': 86400, 'wan': 'up', 'load': '0.42', 'dhcp_leases': 7})

    def test_every_write_is_refused_by_policy(self):
        for name, value in (('uptime', 1), ('wan', 'down'), ('firmware', '9.9'), ('unknown', 1)):
            with self.subTest(name=name), self.assertRaises(OpenwrtRouterBlocked):
                self.dev.set_reversible(name, value)
        for name in ('reboot', 'identify', 'self_destruct'):
            with self.subTest(name=name), self.assertRaises(OpenwrtRouterBlocked):
                self.dev.command(name)
        with self.assertRaises(OpenwrtRouterBlocked):
            self.dev.undo('uptime')
        self.assertNotIn('write', [h[0] for h in self.emu.history])

    def test_graph_entry_is_pseudonymized_and_labelled_emulated(self):
        reg = Registry()
        self.assertEqual(ingest_openwrt_router(reg, self.dev, b'salt', 'SERIAL-1234')['status'], 'OK')
        snap = reg.snapshot()
        self.assertNotIn('SERIAL-1234', json.dumps(snap))
        self.assertEqual({c['status'] for d in snap['devices'] for c in d['capabilities']}, {'SIMULATED_VERIFIED'})


class TransportPolicy(unittest.TestCase):
    def test_local_hosts_only(self):
        for host in ('192.168.1.1', '10.0.0.1', '127.0.0.1', 'openwrt', 'router.lan', 'router.local'):
            self.assertTrue(_host_allowed(host), host)
        for host in ('', '8.8.8.8', 'example.com', 'router.lan.evil.com', 'a/b'):
            self.assertFalse(_host_allowed(host), host)
        with self.assertRaises(OpenwrtRouterBlocked):
            OpenwrtRouterTransport('8.8.8.8')

    def test_only_read_calls_are_sent(self):
        t = OpenwrtRouterTransport('192.168.1.1')
        for obj, method in (('sys', 'exec'), ('uci', 'set'), ('fs', 'write'), ('unknown', 'x')):
            with self.assertRaises(OpenwrtRouterBlocked):
                t.call(obj, method)
        with self.assertRaises(OpenwrtRouterBlocked):
            t.call('fs', 'read', '/etc/shadow')
        with self.assertRaises(OpenwrtRouterBlocked):
            t.write('wan', 'down')
        with self.assertRaises(OpenwrtRouterBlocked):
            t.command('reboot')


class TransportRoundtrip(unittest.TestCase):
    """The transport against a local fake of the LuCI RPC API (loopback HTTP server)."""

    @staticmethod
    def serve():
        from tests.partners.httpfake import json_handler, serve

        def authed(params):
            return bool(params) and params[0] == 'tok-1'

        def auth(h, body):
            req = json.loads(body or b'{}')
            if req.get('method') == 'login' and req.get('params') == ['root', 'secret']:
                return h._send_json({'result': 'tok-1'})
            return h._send_json({'error': 'denied'})

        def sys(h, body):
            req = json.loads(body or b'{}')
            if not authed(req.get('params')):
                return h._send_json({'error': 'bad token'})
            if req.get('method') == 'uptime':
                return h._send_json({'result': 90061})
            return h._send_json({'result': [0.42, 0.31, 0.12]})

        def network(h, body):
            req = json.loads(body or b'{}')
            if not authed(req.get('params')):
                return h._send_json({'error': 'bad token'})
            return h._send_json({'result': {'up': True, 'uptime': 80000}})

        def missing(h, body):
            req = json.loads(body or b'{}')
            if not authed(req.get('params')):
                return h._send_json({'error': 'bad token'})
            return h._send_json({'error': 'no such object'})

        def fs(h, body):
            req = json.loads(body or b'{}')
            if not authed(req.get('params')):
                return h._send_json({'error': 'bad token'})
            return h._send_json({'result': '1700000000 aa:bb:cc:dd:ee:01 192.168.1.10 pi *\n'
                                           '1700000060 aa:bb:cc:dd:ee:02 192.168.1.11 tv *\n'})

        return serve(json_handler({
            ('POST', '/cgi-bin/luci/rpc/auth'): auth,
            ('POST', '/cgi-bin/luci/rpc/sys'): sys,
            ('POST', '/cgi-bin/luci/rpc/network'): network,
            ('POST', '/cgi-bin/luci/rpc/dhcp'): missing,
            ('POST', '/cgi-bin/luci/rpc/fs'): fs,
        }))

    def test_read_roundtrip_with_lease_fallback(self):
        srv = self.serve()
        try:
            t = OpenwrtRouterTransport('127.0.0.1', password='secret', port=srv.server_port)
            dev = OpenwrtRouter(t)
            names = {f['name']: f['value'] for f in dev.facts()}
            self.assertEqual(names, {'uptime': 90061, 'wan': 'up', 'load': '0.42', 'dhcp_leases': 2})
        finally:
            srv.shutdown()
            srv.server_close()

    def test_bad_password_fails_closed(self):
        srv = self.serve()
        try:
            t = OpenwrtRouterTransport('127.0.0.1', password='wrong', port=srv.server_port)
            with self.assertRaises(OpenwrtRouterError):
                OpenwrtRouter(t).facts()
        finally:
            srv.shutdown()
            srv.server_close()


if __name__ == '__main__':
    unittest.main()
